use corpse_core::{startup,pocket_biomes,non_euclidean_generation as ne,portals_generation as pg};
fn main(){for seed in std::env::args().skip(1){let mut r=startup::new_run_shell_revision(&seed,"Unblessed",false,37.).unwrap();if let Err(e)=startup::ensure_floors(&mut r,40){println!("ERROR {seed}: {e}");continue}for f in &r.floors{assert!(pocket_biomes::validate(f),"biome {seed}:{}",f.depth);assert!(ne::validate_floor(f),"links {seed}:{}",f.depth);for b in f.pocket_biomes.as_ref().into_iter().flatten().filter(|b|b.theme=="forest"){println!("FOREST {seed} {} cells{} trees{} grass{}",f.depth,b.cells.len(),b.cells.iter().filter(|i|f.tiles[**i]=="tree").count(),b.cells.iter().filter(|i|f.tiles[**i]=="grass").count());}let corn=f.pocket_biomes.as_ref().into_iter().flatten().find(|b|b.theme=="corn-dimension");let mount=f.pocket_biomes.as_ref().into_iter().flatten().any(|b|b.theme=="mountainous");let ice=f.ice.as_ref().map_or(0,|v|v.iter().filter(|b|**b).count());let hf=f.hellfire.as_ref().map_or(0,|v|v.iter().filter(|b|**b).count());let sp=f.speed_up.as_ref().map_or(0,Vec::len);if let Some(c)=corn {let actors=&r.actors[&(f.depth as u32).to_string()];let residents=actors.iter().filter(|a|c.cells.contains(&(a.y as usize*f.width()+a.x as usize))&&a.creature_kind.as_ref().is_some_and(|k|k.starts_with("horn-"))).count();let portals=f.portals.as_ref().into_iter().flatten().filter(|p|c.cells.contains(&p.a)&&c.cells.contains(&p.b)).count();let speed=f.speed_up.as_ref().into_iter().flatten().filter(|p|p.cells.iter().all(|i|c.cells.contains(i))).count();let rand=f.non_euclidean.as_ref().into_iter().flatten().filter(|p|p.cells.iter().all(|i|c.cells.contains(i))).count();println!("CORN {seed} {} cells{} residents{residents} portals{portals} speed{speed} random{rand} safe{} optional{}",f.depth,c.cells.len(),ne::traversable(f),pg::all_endpoints_optional(f));}if mount||hf>0||sp>0{println!("FLOOR {seed} {} mount{mount} ice{ice} hellfire{hf} speed{sp}",f.depth);}}}}
